class Solution {
  private static boolean atMost(long x, int k, long limit) {
    long p = 1;
    for (int i = 0; i < k; i++) {
      p *= x;
      if (p > limit) return false;
    }
    return true;
  }

  private static long floorRoot(long n, int k) {
    if (n < 0) return -1;
    long lo = 0, hi = 1_000_000_000L;
    while (lo < hi) {
      long mid = (lo + hi + 1) >>> 1;
      if (atMost(mid, k, n)) lo = mid;
      else hi = mid - 1;
    }
    return lo;
  }

  public int countKthRoots(int l, int r, int k) {
    return (int) (floorRoot(r, k) - floorRoot((long) l - 1, k));
  }
}
